const express = require('express');
const crypto = require('crypto');
const session = require('express-session');

const app = express();
app.use(express.urlencoded({ extended: true }));
app.use(session({ secret: 'app-secret-key', resave: false, saveUninitialized: true }));

// Middleware: Generate CSRF token and store in server session
app.get('/transfer', (req, res) => {
  const csrfToken = crypto.randomBytes(32).toString('hex');
  req.session.csrfToken = csrfToken;

  res.send(`
    <form method="POST" action="/transfer">
      <input type="hidden" name="_csrf" value="${csrfToken}">
      <input type="text" name="recipient" placeholder="Recipient">
      <button type="submit">Send Money</button>
    </form>
  `);
});

// POST handler: Validate matching token
app.post('/transfer', (req, res) => {
  const formToken = req.body._csrf;
  const sessionToken = req.session.csrfToken;

  // Strict validation check using constant-time comparison
  if (!formToken || !sessionToken || formToken !== sessionToken) {
    return res.status(403).send('CSRF validation failed: Invalid or missing token');
  }

  // Token is valid; proceed with funds transfer
  res.send('Transfer successful!');
});

/**
 * Double Submit Cookie Pattern:
 * 1. The server sets a non-HttpOnly cookie named 'XSRF-TOKEN' containing a pseudo-random value.
 * 2. On state-changing AJAX requests, JavaScript reads this cookie and copies the value into an HTTP header 'X-XSRF-TOKEN'.
 * 3. The server compares the cookie value with the header value. If they match, the request is trusted.
 */

// Helper to get cookie value by name
function getCookie(name) {
  const match = document.cookie.match(new RegExp('(^| )' + name + '=([^;]+)'));
  return match ? decodeURIComponent(match[2]) : null;
}

async function performSecureAction(payload) {
  const xsrfToken = getCookie('XSRF-TOKEN');

  const response = await fetch('/api/user/profile', {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'X-XSRF-TOKEN': xsrfToken // Injected custom header
    },
    body: JSON.stringify(payload)
  });

  return await response.json();
}

const ALLOWED_ORIGINS = ['https://mybank.com', 'https://auth.mybank.com'];

function verifyOriginReferer(req, res, next) {
  // Safe methods (GET, HEAD, OPTIONS) do not alter server state
  if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) {
    return next();
  }

  // Extract Origin or fallback to Referer
  const sourceOrigin = req.headers['origin'] || (req.headers['referer'] ? new URL(req.headers['referer']).origin : null);

  if (!sourceOrigin) {
    return res.status(403).json({ error: 'Blocked: Request lacks Origin and Referer headers' });
  }

  // Validate against strict whitelist
  if (!ALLOWED_ORIGINS.includes(sourceOrigin)) {
    return res.status(403).json({ error: 'Blocked: Cross-origin request denied' });
  }

  next();
}

module.exports = verifyOriginReferer;
